import itertools
# Semantic ground truth via set inclusion: some sensor x such that {non-grounded drones} is a subset of {y : Mon(y,x)}
def truth(n, S, Dr, G, M):
    N = {y for y in range(n) if Dr[y] and not G[y]}
    return any(S[x] and N <= {y for y in range(n) if M[y][x]} for x in range(n))
def A(n, S, Dr, G, M):
    return all((not (Dr[y] and not G[y])) or any(S[x] and M[y][x] for x in range(n)) for y in range(n))
def B(n, S, Dr, G, M):
    return any((not S[x]) or all((not (Dr[y] and not G[y])) or M[y][x] for y in range(n)) for x in range(n))
def C(n, S, Dr, G, M):
    return any(S[x] and all(Dr[y] and (not G[y]) and M[y][x] for y in range(n)) for x in range(n))
def D(n, S, Dr, G, M):
    return any(S[x] and all((not (Dr[y] and not G[y])) or M[y][x] for y in range(n)) for x in range(n))
bits = lambda k: itertools.product([0, 1], repeat=k)
differ = {"A": 0, "B": 0, "C": 0, "D": 0}; total = 0
for n in (1, 2, 3):
    mats = [tuple(tuple(r[i*n:(i+1)*n]) for i in range(n)) for r in bits(n*n)]
    for S, Dr, G in itertools.product(list(bits(n)), repeat=3):
        for M in mats:
            t = truth(n, S, Dr, G, M); total += 1
            for k, f in (("A", A), ("B", B), ("C", C), ("D", D)):
                if f(n, S, Dr, G, M) != t: differ[k] += 1
print(total, differ)  # D never differs; A, B, C each differ on some interpretations
assert differ["D"] == 0 and all(differ[k] > 0 for k in "ABC")

import itertools
nodes = ["S", "A", "B", "G"]
c = {("S","A"): 2, ("S","B"): 4, ("A","B"): 1, ("A","G"): 7, ("B","G"): 3}
h = {"S": 5, "A": 4, "B": 1, "G": 0}
INF = float("inf")
d = {(u, v): (0 if u == v else c.get((u, v), INF)) for u in nodes for v in nodes}
for k, i, j in itertools.product(nodes, repeat=3):          # Floyd-Warshall all-pairs cheapest costs
    d[i, j] = min(d[i, j], d[i, k] + d[k, j])
hstar = {n: d[n, "G"] for n in nodes}
admissible = all(h[n] <= hstar[n] for n in nodes)
viol = [(u, v) for (u, v), w in c.items() if h[u] > w + h[v]]
consistent = not viol and h["G"] == 0
print(hstar, admissible, consistent, viol)  # {S:6,A:4,B:3,G:0} True False [('A','B')]
verdict = {"A": admissible and consistent, "B": admissible and not consistent,
           "C": consistent and not admissible, "D": not admissible and not consistent}
assert [k for k, v in verdict.items() if v] == ["B"]
